     3	public sealed class CashMachine(IMoneyDispenser dispenser) : ICashMachine
     4	{
     5	    public const int DailyLimit = 200;
     6	    public const int FeeThreshold = 100;
     7	    public const int HighAmountFee = 5;
     8	    public const int CassetteCapacity = 5;
     9	    public const int MaxNotesPerPass = 4;
    10	
    11	    private readonly IMoneyDispenser _dispenser = dispenser ?? throw new ArgumentNullException(nameof(dispenser));
    12	
    13	    public AtmResult Execute(AccountState account, Operation operation) => operation switch
    14	    {
    15	        Operation.Withdraw withdraw => Withdraw(account, withdraw.Amount),
    16	        Operation.Deposit deposit => Deposit(account, deposit.Notes),
    17	        null => throw new ArgumentNullException(nameof(operation)),
    18	        _ => throw new ArgumentException($"Opération inconnue : {operation.GetType().Name}.", nameof(operation)),
    19	    };
    20	
    21	    private AtmResult Withdraw(AccountState account, int amount)
    22	    {
    23	        if (amount <= 0 || amount % 10 != 0)
    24	        {
    25	            return Refuse(AtmStatus.InvalidAmount, account);
    26	        }
    27	
    28	        if (account.WithdrawnToday + amount > DailyLimit)
    29	        {
    30	            return Refuse(AtmStatus.DailyLimitExceeded, account);
    31	        }
    32	
    33	        var fee = amount > FeeThreshold ? HighAmountFee : 0;
    34	        if (amount + fee > account.Balance)
    35	        {
    36	            return Refuse(AtmStatus.InsufficientFunds, account);
    37	        }
    38	
    39	        if (FindFewestNotes(amount, Available()) is not { } combination)
    40	        {
    41	            return Refuse(AtmStatus.CannotDispense, account);
    42	        }
    43	
    44	        var dispensed = NoteCounts.None;
    45	        foreach (var pass in SplitIntoPasses(combination))
    46	        {
    47	            if (!_dispenser.Dispense(pass))
    48	            {
    49	                return new AtmResult(AtmStatus.DispenserFault, dispensed, 0, account);
    50	            }
    51	
    52	            dispensed += pass;
    53	        }
    54	
    55	        var after = new AccountState(account.Balance - amount - fee, account.WithdrawnToday + amount);
    56	
    57	        return new AtmResult(AtmStatus.Ok, combination, fee, after);
    58	    }
    59	
    60	    private AtmResult Deposit(AccountState account, NoteCounts notes)
    61	    {
    62	        if (notes.Total <= 0 || notes.Fifties < 0 || notes.Twenties < 0 || notes.Tens < 0)
    63	        {
    64	            return Refuse(AtmStatus.InvalidAmount, account);
    65	        }
    66	
    67	        if (_dispenser.Jammed is { } jammed && notes.Of(jammed) > 0)
    68	        {
    69	            return Refuse(AtmStatus.CassetteJammed, account);
    70	        }
    71	
    72	        var stock = _dispenser.Stock + notes;
    73	        if (stock.Fifties > CassetteCapacity || stock.Twenties > CassetteCapacity || stock.Tens > CassetteCapacity)
    74	        {
    75	            return Refuse(AtmStatus.CassetteFull, account);
    76	        }
    77	
    78	        if (!_dispenser.Load(notes))
    79	        {
    80	            return Refuse(AtmStatus.DispenserFault, account);
    81	        }
    82	
    83	        var after = account with { Balance = account.Balance + notes.Value };
    84	
    85	        return new AtmResult(AtmStatus.Ok, NoteCounts.None, 0, after);
    86	    }
    87	
    88	    /// <summary>Le stock utilisable : la cassette bloquée compte pour zéro.</summary>
    89	    private NoteCounts Available()
    90	    {
    91	        var stock = _dispenser.Stock;
    92	
    93	        return _dispenser.Jammed switch
    94	        {
    95	            Denomination.Fifty => stock with { Fifties = 0 },
    96	            Denomination.Twenty => stock with { Twenties = 0 },
    97	            Denomination.Ten => stock with { Tens = 0 },
    98	            _ => stock,
    99	        };
   100	    }
   101	
   102	    /// <summary>La combinaison qui fait exactement <paramref name="amount"/> avec le moins de billets, ou <c>null</c>.</summary>
   103	    private static NoteCounts? FindFewestNotes(int amount, NoteCounts available)
   104	    {
   105	        NoteCounts? best = null;
   106	        for (var fifties = Math.Min(Math.Max(available.Fifties, 0), amount / 50); fifties >= 0; fifties--)
   107	        {
   108	            var afterFifties = amount - fifties * 50;
   109	            for (var twenties = Math.Min(Math.Max(available.Twenties, 0), afterFifties / 20); twenties >= 0; twenties--)
   110	            {
   111	                var rest = afterFifties - twenties * 20;
   112	                if (rest % 10 != 0 || rest / 10 > available.Tens)
   113	                {
   114	                    continue;
   115	                }
   116	
   117	                var candidate = new NoteCounts(fifties, twenties, rest / 10);
   118	                if (best is not { } current || candidate.Total < current.Total)
   119	                {
   120	                    best = candidate;
   121	                }
   122	            }
   123	        }
   124	
   125	        return best;
   126	    }
   127	
   128	    /// <summary>Découpe les billets en passages non vides d'au plus <see cref="MaxNotesPerPass"/> billets.</summary>
   129	    private static IEnumerable<NoteCounts> SplitIntoPasses(NoteCounts notes)
   130	    {
   131	        var remaining = notes;
   132	        while (remaining.Total > 0)
   133	        {
   134	            var room = MaxNotesPerPass;
   135	            var fifties = Math.Min(remaining.Fifties, room);
   136	            room -= fifties;
   137	            var twenties = Math.Min(remaining.Twenties, room);
   138	            room -= twenties;
   139	            var tens = Math.Min(remaining.Tens, room);
   140	
   141	            var pass = new NoteCounts(fifties, twenties, tens);
   142	            remaining -= pass;
   143	
   144	            yield return pass;
   145	        }
   146	    }
   147	
   148	    private static AtmResult Refuse(AtmStatus status, AccountState account) =>
   149	        new(status, NoteCounts.None, 0, account);
   150	}
